CREATE VIEW mobilidade.dataset_integrado AS
 SELECT d.data,
    d.viagens,
    c.feriado,
    c.dia_util,
    c.ano,
    c.mes,
    c.dia_semana,
    w.temperatura,
    w.umidade,
    w.vento,
    w.precipitacao
   FROM ((mobilidade.demanda_diaria d
     JOIN mobilidade.calendario c USING (data))
     JOIN mobilidade.clima_diario w USING (localidade_id, data))
  WHERE (d.localidade_id = 1);


